$admin_title='Aparência do Site'; include __DIR__.'/includes/header.php'; $msg='';$erro='';$navOptions=['primary-dark'=>'Cor principal com fonte escura','primary-light'=>'Cor principal com fonte clara','light'=>'Cor clara com fonte escura (padrão)'];
if($_SERVER['REQUEST_METHOD']==='POST'&&$pdo&&verify_csrf($_POST['csrf_token']??null)){foreach(['theme_primary','theme_dark','theme_accent','theme_font','theme_layout','nav_theme'] as $key)save_setting($pdo,$key,trim($_POST[$key]??''));$msg='Aparência atualizada. Veja o resultado no site.';}
?><main class="admin-content"><div class="admin-heading"><div><h1>Aparência do site</h1><p class="muted">Personalize o tema e a barra de navegação.</p></div></div><?php if($msg): ?><div class="notice success"><?= e($msg) ?></div><?php endif; ?><div class="admin-panel"><form class="admin-form appearance-form" method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><h2>Paleta geral</h2><label>Cor principal<input type="color" name="theme_primary" value="<?= e(setting($pdo,'theme_primary','#9f1549')) ?>"></label><label>Cor escura / barra superior<input type="color" name="theme_dark" value="<?= e(setting($pdo,'theme_dark','#74152f')) ?>"></label><label>Cor de destaque<input type="color" name="theme_accent" value="<?= e(setting($pdo,'theme_accent','#ef5d98')) ?>"></label><label>Tipografia<select name="theme_font"><option value="DM Sans" <?= setting($pdo,'theme_font','DM Sans')==='DM Sans'?'selected':'' ?>>DM Sans</option><option value="Inter" <?= setting($pdo,'theme_font','')==='Inter'?'selected':'' ?>>Inter</option><option value="Arial" <?= setting($pdo,'theme_font','')==='Arial'?'selected':'' ?>>Arial</option></select></label><label>Largura do layout<select name="theme_layout"><option value="wide" <?= setting($pdo,'theme_layout','wide')==='wide'?'selected':'' ?>>Largo</option><option value="boxed" <?= setting($pdo,'theme_layout','')==='boxed'?'selected':'' ?>>Compacto</option></select></label><hr><h2>Barra de navegação</h2><label>Esquema de contraste<select name="nav_theme"><?php foreach($navOptions as $key=>$label): ?><option value="<?= e($key) ?>" <?= setting($pdo,'nav_theme','light')===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select><small class="muted">A seleção é aplicada como classe CSS na navegação pública.</small></label><button class="btn btn-primary">Salvar aparência</button></form></div></main><?php include __DIR__.'/includes/footer.php'; ?>
